{
  "name": "RPLIDAR激光雷达",
  "name_en": "RPLIDAR LiDAR",
  "manufacturer": "",
  "description": "用于机器人环境感知的二维激光雷达。该设备通过连续扫描获取距离与角度测量数据，可用于避障、定位、建图和周围环境轮廓检测。",
  "description_en": "A 2D LiDAR sensor for robot environment perception. It continuously scans to acquire distance and angle measurements, enabling obstacle avoidance, localization, mapping, and surrounding scene detection.",
  "actions": [
    {
      "action_name": "auto-update",
      "description": "更新并读取最新的激光雷达扫描测量数据。",
      "description_en": "Update and read the latest LiDAR scan measurements."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "在线程模式下返回当前缓存的激光雷达扫描数据。",
      "description_en": "Return the currently cached LiDAR scan data in threaded mode."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止激光雷达采集并关闭设备连接。",
      "description_en": "Stop LiDAR acquisition and close the device connection."
    }
  ],
  "tag_hints": [
    "2D LiDAR",
    "laser ranging",
    "robot navigation",
    "obstacle detection",
    "SLAM",
    "distance-angle scan"
  ]
}

